import { ruinRules, validateRuinRules, type RuinRules } from "@pirate-sea-race/content/ruins";
import { drawInt, generateNavigation, generateSequence, puzzleClue, type Draw, type RuinClue, type RuinPuzzle } from "./puzzles.js";

/** A player reading a ruin's clue, since `openedTick`. */
export interface RuinSession {
  readonly playerId: string;
  readonly openedTick: number;
}

/** A player's lockout at one ruin: no attempt before `until`. It outlives sessions, so leaving does not clear it. */
export interface RuinLockout {
  readonly playerId: string;
  readonly until: number;
}

export interface RuinSolve {
  readonly playerId: string;
  readonly tick: number;
}

/** One regular island's ruin, guarding all of that island's sources. */
export interface Ruin {
  readonly island: number;
  /** The ledger's ids of the island's sources (`source-<island>-<slot>`), as the caller supplied them. */
  readonly sourceIds: readonly string[];
  /** Secret: holds the answer. Only `clueFor` may leave the server. */
  readonly puzzle: RuinPuzzle;
  /** Set by the first solve, for everyone. */
  readonly unlocked: boolean;
  /** In solve order; each player at most once. */
  readonly solvedBy: readonly RuinSolve[];
  /** Sorted by player id. */
  readonly lockouts: readonly RuinLockout[];
  /** Sorted by player id. */
  readonly sessions: readonly RuinSession[];
}

/** Where the caller last reported a player: moored at an island's dock (`island`), and whether in a duel. */
export interface RuinPresence {
  readonly playerId: string;
  readonly island: number | null;
  readonly inDuel: boolean;
}

/** All the ruins of a match: plain integer data that `hashState` covers entirely. */
export interface RuinsState {
  readonly rules: RuinRules;
  /** The latest world tick an applied request carried. Requests from earlier ticks are stale. */
  readonly tick: number;
  /** By island number. */
  readonly ruins: Readonly<Record<string, Ruin>>;
  /** Players away from every ruin and out of any duel have no entry. Sorted by player id. */
  readonly presence: readonly RuinPresence[];
}

export interface RuinIsland {
  readonly island: number;
  readonly sourceIds: readonly string[];
}

export interface CreateRuinsOptions {
  /** The match's private seed. */
  readonly seed: number;
  /** Every regular island (not the final one) with its ledger source ids. */
  readonly islands: readonly RuinIsland[];
  readonly rules?: RuinRules;
}

/** Mixed into the match seed so the ruins draw from their own stream, apart from the ledger's source deal. */
const RUINS_STREAM = 0x5255494e;

function islandIssues(islands: readonly RuinIsland[]): string[] {
  const issues: string[] = [];
  const seen = new Set<number>();
  islands.forEach((entry, index) => {
    const island = entry?.island;
    if (!Number.isSafeInteger(island) || island < 0) {
      issues.push(`islands.${index}: an island is a non-negative integer`);
      return;
    }
    if (seen.has(island)) issues.push(`islands.${index}: island ${island} appears twice`);
    seen.add(island);
    const ids = entry.sourceIds;
    if (!Array.isArray(ids) || ids.length === 0) {
      issues.push(`islands.${index}: island ${island} needs its source ids`);
      return;
    }
    const pattern = new RegExp(`^source-${island}-[0-9]+$`);
    ids.forEach((id, slot) => {
      if (typeof id !== "string" || !pattern.test(id)) issues.push(`islands.${index}.sourceIds.${slot}: ${String(id)} is not a source of island ${island}`);
    });
    if (new Set(ids).size !== ids.length) issues.push(`islands.${index}: island ${island} repeats a source id`);
  });
  return issues;
}

/**
 * A match's ruins, dealt once at match creation: in island order, each ruin draws its kind (sequence or navigation)
 * and then its puzzle from the seeded generator. The same seed and islands always give the same ruins, in whatever
 * order the islands are listed.
 */
export function createRuins(options: CreateRuinsOptions): RuinsState {
  if (!Number.isSafeInteger(options.seed)) throw new RangeError(`seed must be an integer, got ${options.seed}`);
  const rules = validateRuinRules(options.rules ?? ruinRules);
  if (!rules.ok) throw new Error(`invalid ruin rules: ${rules.issues.join("; ")}`);
  const issues = islandIssues(options.islands);
  if (issues.length > 0) throw new Error(`invalid ruin islands: ${issues.join("; ")}`);
  const source: Draw = { rng: (options.seed ^ RUINS_STREAM) >>> 0 };
  const ruins: Record<string, Ruin> = {};
  for (const { island, sourceIds } of [...options.islands].sort((a, b) => a.island - b.island)) {
    const puzzle = drawInt(source, 2) === 0 ? generateSequence(rules.value, source) : generateNavigation(rules.value, source);
    ruins[String(island)] = { island, sourceIds: [...sourceIds], puzzle, unlocked: false, solvedBy: [], lockouts: [], sessions: [] };
  }
  return { rules: rules.value, tick: 0, ruins, presence: [] };
}

/** The ruin on an island, if it has one. */
export function findRuin(state: RuinsState, island: number): Ruin | undefined {
  return Object.hasOwn(state.ruins, String(island)) ? state.ruins[String(island)] : undefined;
}

/** The islands with ruins, in ascending order. */
export function ruinIslands(state: RuinsState): number[] {
  return Object.values(state.ruins)
    .map((ruin) => ruin.island)
    .sort((a, b) => a - b);
}

/** The only view of a ruin a client may receive (§16): the site's clue, never the answer. */
export function clueFor(ruin: Ruin): RuinClue {
  return puzzleClue(ruin.puzzle);
}

export function presenceOf(state: RuinsState, playerId: string): RuinPresence {
  return state.presence.find((entry) => entry.playerId === playerId) ?? { playerId, island: null, inDuel: false };
}

export function lockedUntil(ruin: Ruin, playerId: string): number {
  return ruin.lockouts.find((lockout) => lockout.playerId === playerId)?.until ?? 0;
}

export function sessionOf(ruin: Ruin, playerId: string): RuinSession | undefined {
  return ruin.sessions.find((session) => session.playerId === playerId);
}

export function hasSolved(ruin: Ruin, playerId: string): boolean {
  return ruin.solvedBy.some((solve) => solve.playerId === playerId);
}
import { RUIN_MOVES, type RuinSymbol } from "@pirate-sea-race/content/ruins";
import { attemptSolves, type RuinAttempt, type RuinClue } from "./puzzles.js";
import {
  clueFor,
  findRuin,
  hasSolved,
  lockedUntil,
  presenceOf,
  sessionOf,
  type Ruin,
  type RuinPresence,
  type RuinsState,
} from "./state.js";

/**
 * Why a request changed nothing (§16: duplicate, stale or refused requests return the current result without
 * mutating state). A rejected request always returns the very state object it was given. No rejection depends on the
 * answer: a malformed attempt is refused for its shape alone, and a well-formed wrong one is a wrong answer.
 */
export type RuinRejection =
  | "invalid-request"
  | "stale-tick"
  | "duplicate"
  | "unknown-ruin"
  | "not-at-ruin"
  | "in-duel"
  | "no-session"
  | "already-solved"
  | "locked-out";

/**
 * What the caller applies to the ledger later:
 * - `sources-unlocked`: the first solve of a ruin, once per ruin; `unlockSource` for each id.
 * - `gold-awarded`: a player's first solve of a ruin, once per player and ruin; new gold (§11).
 */
export type RuinEvent =
  | { readonly kind: "sources-unlocked"; readonly island: number; readonly sourceIds: readonly string[]; readonly playerId: string; readonly tick: number }
  | { readonly kind: "gold-awarded"; readonly island: number; readonly playerId: string; readonly amount: number; readonly tick: number };

/** What every operation returns: the next state (the same object when nothing changed) and its result. */
export interface RuinStep<R> {
  readonly state: RuinsState;
  readonly result: R;
}

function isTick(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

function isPlayerId(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isIsland(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

function tickRejection(state: RuinsState, tick: unknown): RuinRejection | null {
  if (!isTick(tick)) return "invalid-request";
  return tick < state.tick ? "stale-tick" : null;
}

function byPlayer<T extends { readonly playerId: string }>(a: T, b: T): number {
  return a.playerId < b.playerId ? -1 : a.playerId > b.playerId ? 1 : 0;
}

/** Puts (or with null, removes) a player's entry in a list sorted by player id. */
function upsert<T extends { readonly playerId: string }>(list: readonly T[], playerId: string, entry: T | null): T[] {
  const rest = list.filter((item) => item.playerId !== playerId);
  return entry === null ? rest : [...rest, entry].sort(byPlayer);
}

function withRuin(state: RuinsState, ruin: Ruin): RuinsState {
  return { ...state, ruins: { ...state.ruins, [String(ruin.island)]: ruin } };
}

// ---------------------------------------------------------------------------------------------------------------
// Presence

export interface ReportPresenceRequest {
  readonly playerId: string;
  /** The island whose dock the player is moored at, or null when at sea (or anywhere without a ruin). */
  readonly island: number | null;
  readonly inDuel: boolean;
  readonly tick: number;
}

export interface PresenceResult {
  readonly ok: boolean;
  readonly rejection: RuinRejection | null;
  /** The islands whose ruin session this report closed. */
  readonly closed: readonly number[];
}

/**
 * The caller reports where a player is whenever it changes (it may report every tick; an unchanged report is a
 * duplicate). Being elsewhere than a ruin's island, or in a duel, closes the player's session there. Lockouts stay.
 */
export function reportPresence(state: RuinsState, request: ReportPresenceRequest): RuinStep<PresenceResult> {
  const { playerId, island, inDuel, tick } = request;
  const reject = (rejection: RuinRejection): RuinStep<PresenceResult> => ({ state, result: { ok: false, rejection, closed: [] } });
  const bad = tickRejection(state, tick);
  if (bad) return reject(bad);
  if (!isPlayerId(playerId) || (island !== null && !isIsland(island)) || typeof inDuel !== "boolean") return reject("invalid-request");
  const current = presenceOf(state, playerId);
  if (current.island === island && current.inDuel === inDuel) return reject("duplicate");
  const closed: number[] = [];
  const ruins: Record<string, Ruin> = { ...state.ruins };
  for (const [key, ruin] of Object.entries(state.ruins)) {
    if (!sessionOf(ruin, playerId) || (!inDuel && ruin.island === island)) continue;
    ruins[key] = { ...ruin, sessions: upsert(ruin.sessions, playerId, null) };
    closed.push(ruin.island);
  }
  const entry: RuinPresence | null = island === null && !inDuel ? null : { playerId, island, inDuel };
  const next: RuinsState = { ...state, tick, ruins, presence: upsert(state.presence, playerId, entry) };
  return { state: next, result: { ok: true, rejection: null, closed: closed.sort((a, b) => a - b) } };
}

// ---------------------------------------------------------------------------------------------------------------
// Opening a ruin

export interface OpenRuinRequest {
  readonly playerId: string;
  readonly island: number;
  readonly tick: number;
}

export interface OpenResult {
  readonly ok: boolean;
  readonly rejection: RuinRejection | null;
  /** The clue, for a player with a session at this ruin (a repeated open gets it again); otherwise null. */
  readonly clue: RuinClue | null;
  /** The tick before which this player's attempts here are refused; 0 when never locked out. */
  readonly lockedUntil: number;
  /** Whether this player has already solved this ruin. */
  readonly solved: boolean;
}

/** Starts a player's session at the ruin of the island they are moored at and hands them its clue. */
export function openRuin(state: RuinsState, request: OpenRuinRequest): RuinStep<OpenResult> {
  const { playerId, island, tick } = request;
  const ruin = isIsland(island) ? findRuin(state, island) : undefined;
  const reject = (rejection: RuinRejection): RuinStep<OpenResult> => {
    const session = ruin && isPlayerId(playerId) ? sessionOf(ruin, playerId) : undefined;
    return {
      state,
      result: {
        ok: false,
        rejection,
        clue: session ? clueFor(ruin!) : null,
        lockedUntil: ruin && isPlayerId(playerId) ? lockedUntil(ruin, playerId) : 0,
        solved: ruin !== undefined && isPlayerId(playerId) && hasSolved(ruin, playerId),
      },
    };
  };
  const bad = tickRejection(state, tick);
  if (bad) return reject(bad);
  if (!isPlayerId(playerId) || !isIsland(island)) return reject("invalid-request");
  if (!ruin) return reject("unknown-ruin");
  const presence = presenceOf(state, playerId);
  if (presence.inDuel) return reject("in-duel");
  if (presence.island !== island) return reject("not-at-ruin");
  if (sessionOf(ruin, playerId)) return reject("duplicate");
  const opened: Ruin = { ...ruin, sessions: upsert(ruin.sessions, playerId, { playerId, openedTick: tick }) };
  return {
    state: withRuin({ ...state, tick }, opened),
    result: { ok: true, rejection: null, clue: clueFor(opened), lockedUntil: lockedUntil(ruin, playerId), solved: hasSolved(ruin, playerId) },
  };
}

// ---------------------------------------------------------------------------------------------------------------
// Answering

export interface AnswerRuinRequest {
  readonly playerId: string;
  readonly island: number;
  readonly tick: number;
  readonly attempt: RuinAttempt;
}

export type AnswerOutcome = "solved" | "wrong";

export interface AnswerResult {
  readonly ok: boolean;
  readonly rejection: RuinRejection | null;
  readonly outcome: AnswerOutcome | null;
  /** The tick before which this player's attempts here are refused; 0 when never locked out. */
  readonly lockedUntil: number;
  /** For the caller to apply to the ledger, in order. */
  readonly events: readonly RuinEvent[];
}

/**
 * Whether an attempt has a well-formed shape for the ruin's kind, which the clue already tells: a sequence of the
 * right length of distinct known symbols, or one to `size²` compass moves. The check never looks at the answer.
 */
function attemptShapeOk(state: RuinsState, ruin: Ruin, attempt: unknown): attempt is RuinAttempt {
  if (typeof attempt !== "object" || attempt === null) return false;
  const candidate = attempt as Record<string, unknown>;
  if (candidate.kind !== ruin.puzzle.kind) return false;
  if (ruin.puzzle.kind === "sequence") {
    const symbols = candidate.symbols;
    if (!Array.isArray(symbols) || symbols.length !== ruin.puzzle.answer.length) return false;
    const known: readonly string[] = state.rules.symbols;
    return symbols.every((symbol) => typeof symbol === "string" && known.includes(symbol)) && new Set(symbols as RuinSymbol[]).size === symbols.length;
  }
  const moves = candidate.moves;
  const longest = ruin.puzzle.size * ruin.puzzle.size;
  const compass: readonly string[] = RUIN_MOVES;
  return Array.isArray(moves) && moves.length > 0 && moves.length <= longest && moves.every((move) => typeof move === "string" && compass.includes(move));
}

/**
 * Checks a player's attempt at the ruin they have open. A right answer solves the ruin for that player: the first
 * solve unlocks the island's sources for everyone, and every player's first solve pays the completion gold. A wrong
 * answer locks that player out of that ruin for `lockoutTicks`.
 */
export function answerRuin(state: RuinsState, request: AnswerRuinRequest): RuinStep<AnswerResult> {
  const { playerId, island, tick, attempt } = request;
  const ruin = isIsland(island) ? findRuin(state, island) : undefined;
  const reject = (rejection: RuinRejection): RuinStep<AnswerResult> => ({
    state,
    result: { ok: false, rejection, outcome: null, lockedUntil: ruin && isPlayerId(playerId) ? lockedUntil(ruin, playerId) : 0, events: [] },
  });
  const bad = tickRejection(state, tick);
  if (bad) return reject(bad);
  if (!isPlayerId(playerId) || !isIsland(island)) return reject("invalid-request");
  if (!ruin) return reject("unknown-ruin");
  const presence = presenceOf(state, playerId);
  if (presence.inDuel) return reject("in-duel");
  if (presence.island !== island) return reject("not-at-ruin");
  if (!sessionOf(ruin, playerId)) return reject("no-session");
  if (hasSolved(ruin, playerId)) return reject("already-solved");
  if (tick < lockedUntil(ruin, playerId)) return reject("locked-out");
  if (!attemptShapeOk(state, ruin, attempt)) return reject("invalid-request");

  if (!attemptSolves(ruin.puzzle, attempt)) {
    const until = tick + state.rules.lockoutTicks;
    const locked: Ruin = { ...ruin, lockouts: upsert(ruin.lockouts, playerId, { playerId, until }) };
    return { state: withRuin({ ...state, tick }, locked), result: { ok: true, rejection: null, outcome: "wrong", lockedUntil: until, events: [] } };
  }
  const events: RuinEvent[] = [];
  if (!ruin.unlocked) events.push({ kind: "sources-unlocked", island: ruin.island, sourceIds: [...ruin.sourceIds], playerId, tick });
  events.push({ kind: "gold-awarded", island: ruin.island, playerId, amount: state.rules.completionGold, tick });
  const solved: Ruin = { ...ruin, unlocked: true, solvedBy: [...ruin.solvedBy, { playerId, tick }] };
  return {
    state: withRuin({ ...state, tick }, solved),
    result: { ok: true, rejection: null, outcome: "solved", lockedUntil: lockedUntil(ruin, playerId), events },
  };
}
import { RUIN_MOVES, type RuinMove, type RuinRules, type RuinSymbol } from "@pirate-sea-race/content/ruins";
import { nextInt } from "../random.js";

/**
 * What one tablet says about its own symbol. Positions count from 0. Every hint the generator writes is true of the
 * answer, and the six hints together admit exactly one sequence.
 *
 * - `absent` / `present`: the symbol is not / is in the sequence.
 * - `at` / `not-at`: the symbol is / is not at `position` (an absent symbol is at no position).
 * - `right-after` / `right-before`: both are in the sequence, the symbol immediately after / before `other`.
 * - `after` / `before`: both are in the sequence, the symbol somewhere after / before `other`.
 */
export type SequenceRelation =
  | "absent"
  | "present"
  | "at"
  | "not-at"
  | "right-after"
  | "right-before"
  | "after"
  | "before";

export interface SequenceHint {
  readonly relation: SequenceRelation;
  /** The symbol the relation refers to, for the four relational hints; otherwise null. */
  readonly other: RuinSymbol | null;
  /** The position of `at` and `not-at`; otherwise null. */
  readonly position: number | null;
}

/** A carved tablet at the site: a symbol and its hint. A sequence ruin shows one for every symbol. */
export interface SequenceTablet {
  readonly symbol: RuinSymbol;
  readonly hint: SequenceHint;
}

export interface SequencePuzzle {
  readonly kind: "sequence";
  /** Secret: the symbols in order. */
  readonly answer: readonly RuinSymbol[];
  /** Every symbol of the rules, in the rules' fixed order, whatever the answer. */
  readonly tablets: readonly SequenceTablet[];
}

/** A grid cell: x grows east, y grows south. */
export interface Cell {
  readonly x: number;
  readonly y: number;
}

export interface NavigationPuzzle {
  readonly kind: "navigation";
  readonly size: number;
  readonly start: Cell;
  readonly goal: Cell;
  /** Sorted by row, then column. */
  readonly blocked: readonly Cell[];
  /** Secret, though a reader can work it out: the number of moves of every accepted answer. */
  readonly minMoves: number;
}

export type RuinPuzzle = SequencePuzzle | NavigationPuzzle;
export type RuinKind = RuinPuzzle["kind"];

/** The only view of a ruin a client may receive (§16): what the site shows, never the answer. */
export type RuinClue =
  | { readonly kind: "sequence"; readonly length: number; readonly tablets: readonly SequenceTablet[] }
  | { readonly kind: "navigation"; readonly size: number; readonly start: Cell; readonly goal: Cell; readonly blocked: readonly Cell[] };

export type RuinAttempt =
  | { readonly kind: "sequence"; readonly symbols: readonly RuinSymbol[] }
  | { readonly kind: "navigation"; readonly moves: readonly RuinMove[] };

/** A threaded seeded generator: each draw advances `rng`. */
export interface Draw {
  rng: number;
}

/** An integer in [0, bound) from the threaded generator. */
export function drawInt(source: Draw, bound: number): number {
  const drawn = nextInt(source.rng, bound);
  source.rng = drawn.state;
  return drawn.value;
}

// ---------------------------------------------------------------------------------------------------------------
// Sequence puzzles

/** Whether a hint about `symbol` holds for the candidate sequence `order`. */
export function sequenceHintHolds(symbol: RuinSymbol, hint: SequenceHint, order: readonly RuinSymbol[]): boolean {
  const index = order.indexOf(symbol);
  const other = hint.other === null ? -1 : order.indexOf(hint.other);
  switch (hint.relation) {
    case "absent":
      return index < 0;
    case "present":
      return index >= 0;
    case "at":
      return index >= 0 && index === hint.position;
    case "not-at":
      return index !== hint.position;
    case "right-after":
      return index >= 0 && other >= 0 && index === other + 1;
    case "right-before":
      return index >= 0 && other >= 0 && index + 1 === other;
    case "after":
      return index >= 0 && other >= 0 && index > other;
    case "before":
      return index >= 0 && other >= 0 && index < other;
  }
}

/** Every ordered sequence of `length` distinct symbols (120 for six symbols and three places). */
export function allSequences(symbols: readonly RuinSymbol[], length: number): RuinSymbol[][] {
  if (length === 0) return [[]];
  return symbols.flatMap((symbol) =>
    allSequences(
      symbols.filter((other) => other !== symbol),
      length - 1,
    ).map((rest) => [symbol, ...rest]),
import { z } from "zod";
import { formatIssues, type ValidationResult } from "../rules.js";
import { WORLD_STEPS_PER_SECOND } from "../sailing.js";

/** §3: a wrong attempt at a ruin locks that player out of that ruin this long. */
export const RUIN_LOCKOUT_SECONDS = 3;
/** §11: a fresh ruin completion pays this much, once per player per ruin. */
export const RUIN_COMPLETION_GOLD = 40;
/** The six carved symbols of a sequence ruin, in their fixed display order. */
export const RUIN_SYMBOLS = ["sun", "moon", "tide", "storm", "anchor", "skull"] as const;
/** A sequence ruin's answer: this many distinct symbols in order. */
export const RUIN_SEQUENCE_LENGTH = 3;
/** A navigation ruin's grid is this many cells on a side. */
export const RUIN_GRID_SIZE = 4;
/** A navigation ruin's shortest path from start to goal is this many moves or more… */
export const RUIN_MIN_PATH_MOVES = 4;
/** …and this many or fewer. */
export const RUIN_MAX_PATH_MOVES = 6;
/** A navigation ruin blocks this many cells or more… */
export const RUIN_MIN_BLOCKED_CELLS = 3;
/** …and this many or fewer. */
export const RUIN_MAX_BLOCKED_CELLS = 5;

export const ruinSymbolSchema = z.enum(RUIN_SYMBOLS);
export type RuinSymbol = z.infer<typeof ruinSymbolSchema>;

/** The compass moves of a navigation answer. North is towards smaller y (y grows down, as on the sea). */
export const RUIN_MOVES = ["N", "E", "S", "W"] as const;
export const ruinMoveSchema = z.enum(RUIN_MOVES);
export type RuinMove = z.infer<typeof ruinMoveSchema>;

/** The ruin rules (§3, §11) in world ticks (20 a second), gold and cells. */
export const ruinRulesSchema = z
  .strictObject({
    /** World ticks a wrong attempt locks the player out of that ruin. */
    lockoutTicks: z.int().nonnegative(),
    /** Gold for each player's first solve of each ruin. */
    completionGold: z.int().nonnegative(),
    /** The symbols a sequence ruin shows, in display order. */
    symbols: z.array(ruinSymbolSchema).min(1),
    sequenceLength: z.int().positive(),
    gridSize: z.int().min(2),
    minPathMoves: z.int().positive(),
    maxPathMoves: z.int().positive(),
    minBlockedCells: z.int().nonnegative(),
    maxBlockedCells: z.int().nonnegative(),
  })
  .superRefine((rules, ctx) => {
    const issue = (path: string, message: string) => ctx.addIssue({ code: "custom", path: [path], message });
    if (new Set(rules.symbols).size !== rules.symbols.length) issue("symbols", "the symbols must be distinct");
    if (rules.sequenceLength >= rules.symbols.length) {
      issue("sequenceLength", `a sequence of ${rules.sequenceLength} needs more than ${rules.symbols.length} symbols, or every symbol is in it`);
    }
    if (rules.minPathMoves > rules.maxPathMoves) {
      issue("minPathMoves", `the path range ${rules.minPathMoves}–${rules.maxPathMoves} is empty`);
    }
    if (rules.minBlockedCells > rules.maxBlockedCells) {
      issue("minBlockedCells", `the blocked-cell range ${rules.minBlockedCells}–${rules.maxBlockedCells} is empty`);
    }
    const cells = rules.gridSize * rules.gridSize;
    // A shortest path visits distinct open cells, so it has at most (open cells - 1) moves.
    const longest = cells - rules.minBlockedCells - 1;
    if (rules.minPathMoves > longest) {
      issue("minPathMoves", `a ${rules.gridSize} × ${rules.gridSize} grid with ${rules.minBlockedCells} blocked cells holds no path of ${rules.minPathMoves} moves`);
    }
    if (rules.maxBlockedCells > cells - 2) {
      issue("maxBlockedCells", `a ${rules.gridSize} × ${rules.gridSize} grid needs an open start and goal`);
    }
  });

export type RuinRules = z.infer<typeof ruinRulesSchema>;

export const ruinRules: RuinRules = {
  lockoutTicks: RUIN_LOCKOUT_SECONDS * WORLD_STEPS_PER_SECOND,
  completionGold: RUIN_COMPLETION_GOLD,
  symbols: [...RUIN_SYMBOLS],
  sequenceLength: RUIN_SEQUENCE_LENGTH,
  gridSize: RUIN_GRID_SIZE,
  minPathMoves: RUIN_MIN_PATH_MOVES,
  maxPathMoves: RUIN_MAX_PATH_MOVES,
  minBlockedCells: RUIN_MIN_BLOCKED_CELLS,
  maxBlockedCells: RUIN_MAX_BLOCKED_CELLS,
