93	    const players: ClaimPlayer[] = [];
94	    for (const ship of this.simulation.ships) {
95	      const player = findPlayer(this.ledger, ship.id);
96	      if (player === undefined || player.status === "left") continue;
97	      const gate = this.gates.get(ship.id);
98	      players.push({
99	        id: ship.id,
100	        x: ship.x,
101	        y: ship.y,
102	        speed: ship.speed,
103	        holdsAllTypes: holdsAllTypes(this.ledger, ship.id),
104	        interact: !held.has(ship.id) && gate !== undefined && !gate.lapsedAt(frame) && (gate.inputAt(frame).buttons & INTERACT_BUTTON) !== 0,
105	        connected: player.status === "connected" && this.clients.get(ship.id) !== undefined,
106	        protected: (records.get(ship.id)?.protection ?? null) !== null,
107	      });
108	    }
109	    const encounters = this.encounters.duels.map((duel) => ({ id: duel.id, playerIds: duel.players }));
110	    const stepped = stepClaim(this.claimConfig, this.claim, { tick, players, encounters });
111	    this.claim = stepped.state;
112	    let end: FlowReport | undefined;
113	    for (const event of stepped.events) end = this.applyClaimEvent(event) ?? end;
114	    return end;
115	  }
116	
117	  private applyClaimEvent(event: ClaimEvent): FlowReport | undefined {
118	    switch (event.kind) {
119	      case "claim-interrupted": {
120	        const notice = this.noticesOf(event.playerId);
121	        notice.claimInterrupt = event.reason;
122	        notice.claimInterruptAt = event.tick;
123	        return undefined;
124	      }
125	      case "claim-started":
126	        this.noticesOf(event.playerId).claimInterrupt = "";
127	        return undefined;
128	      case "protection-ended":
129	        // §6: claiming ends protection; the encounter rules hear it on the next tick.
130	        this.protectionEndedNext.set(event.playerId, "claim");
131	        return undefined;
132	      case "match-ended":
133	        return { kind: "match-ended", tick: event.tick, reason: event.reason, winner: event.winner };
134	      default:
135	        // `claim-completed` shows in the results; `duel-ended-without-theft` is applied when the match ends.
136	        return undefined;
137	    }
138	  }
