140	  /**
141	   * The accomplishments of this tick (§2's results), read from the ledger, which alone moves rubbings and gold: each
142	   * rubbing that changed hands since the last tick (from a source: collected; from a cache: a cache claimed; from one
143	   * player to another: a theft and a loss; from a player into a cache: a loss), each balance that changed, and each
144	   * island a player first moors at.
145	   */
146	  private reportAccomplishments(_tick: number): void {
147	    // Unknown ids are dropped with every other report's, before the flow's step (`knownFlowReports`).
148	    const report = (entry: FlowReport) => this.flowReports.push(entry);
149	    for (const rubbing of this.ledger.rubbings) {
150	      const before = this.lastLocations.get(rubbing.id);
151	      this.lastLocations.set(rubbing.id, rubbing.location);
152	      // The first tick in play only records where each rubbing is.
153	      if (before === undefined) continue;
154	      const from = holderOf(before);
155	      const to = holderOf(rubbing.location);
156	      if (from === to) continue;
157	      if (from === undefined && to !== undefined) {
158	        if (before.kind === "source") report({ kind: "collected", playerId: to });
159	        else if (before.kind === "cache") report({ kind: "cache-claimed", playerId: to });
160	      } else if (from !== undefined && to !== undefined) {
161	        report({ kind: "stole", playerId: to });
162	        report({ kind: "lost", playerId: from });
163	      } else if (from !== undefined) {
164	        report({ kind: "lost", playerId: from });
165	      }
166	    }
167	    for (const player of this.ledger.players) {
168	      if (this.reportedGold.get(player.id) === player.gold) continue;
169	      this.reportedGold.set(player.id, player.gold);
170	      report({ kind: "gold", playerId: player.id, gold: player.gold });
171	    }
172	    for (const ship of this.simulation.ships) {
173	      const island = ship.dock === NOT_DOCKED ? -1 : (this.config.map.docks[ship.dock]?.island ?? -1);
174	      if (island < 0 || this.visited.has(`${ship.id}:${island}`)) continue;
175	      this.visited.add(`${ship.id}:${island}`);
176	      report({ kind: "island-visited", playerId: ship.id, island: String(island) });
177	    }
178	  }
