180	  /**
181	   * §2's match flow, one world tick: the joins, leaves and start requests since the last tick, this tick's
182	   * accomplishments and the claim's end, in that order. Reports naming a player the flow does not know are dropped
183	   * first (`knownFlowReports`: the match module throws on them), and counted for tests.
184	   */
185	  private stepFlow(tick: number, claimEnd?: FlowReport): void {
186	    const reports = this.flowReports;
187	    this.flowReports = [];
188	    if (claimEnd !== undefined) reports.push(claimEnd);
189	    this.stepFlowWith(tick, reports);
190	  }
191	
192	  private stepFlowWith(tick: number, reports: readonly FlowReport[]): void {
193	    const known = knownFlowReports(this.flow.players, reports);
194	    this.droppedReports.push(...known.dropped);
195	    const stepped = stepMatch(this.flowConfig, this.flow, { tick, reports: known.reports });
196	    this.flow = stepped.state;
197	    for (const event of stepped.events) this.applyFlowEvent(event);
198	  }
199	
200	  private applyFlowEvent(event: FlowEvent): void {
201	    switch (event.kind) {
202	      case "start-refused":
203	        this.clients.get(event.playerId)?.send(MatchMessageType.StartRefused, { reason: event.reason } satisfies StartRefusedMessage);
204	        return;
205	      // No `join-refused`: the room reports a join only in the lobby (onJoin refuses one after it), before any start
206	      // in the same step, and seats no more players than the flow has seats (docs/match-online-coverage.md).
207	      case "phase-changed":
208	        // §2: once the ready countdown starts, admission refuses late arrivals; back in the lobby, it admits again.
209	        if (event.to === "ready" || event.to === "lobby") void this.setMatchmaking({ metadata: { code: this.state.code, custom: privateMatch.custom, started: event.to === "ready" } });
210	        return;
211	      case "control-started":
212	        this.startControl(event.tick);
213	        return;
214	      case "match-ended":
215	        this.endMatch(event.results);
216	        return;
217	      default:
218	        return;
219	    }
220	  }
