222	  /**
223	   * §2's control start: every ship present gets the encounter rules' departure protection from this tick, the claim
224	   * config's deadline counts from it (the timer's end), and the reveals' clocks start. The accomplishments start from
225	   * the first tick in play, which records where each rubbing is and each balance (the starting gold).
226	   */
227	  private startControl(tick: number): void {
228	    // Every ship's player is in the match (the room's invariant): a leave removes the ship at once.
229	    const ids = this.simulation.ships.map((ship) => ship.id);
230	    this.encounters = createEncounterState(this.encounterConfig, { tick, spawnProtected: ids });
231	    this.claimConfig = claimConfigFor(this.tuning, this.finalIsland.claimPoint, tick, this.config.map);
232	    this.claim = createClaimState(this.claimConfig, tick);
233	    this.intelConfig = intelConfigFor(this.tuning, this.finalIsland.claimPoint, tick, this.config.map);
234	    this.intel = createIntelState(this.intelConfig, this.seedOf("intel"), tick - 1);
235	  }
