237	  /**
238	   * The match is over (§2, §5): outcomes freeze. A duel still running ends without theft (§2), each fighter's lobby
239	   * showing the cancellation for a moment; the ships stop taking input; the results are the flow's, recorded once.
240	   */
241	  private endMatch(results: MatchResults): void {
242	    const tick = results.tick;
243	    for (const duel of this.seaDuels.values()) {
244	      if (findDuel(this.ledger, duel.id)?.phase === "fighting" && tick >= this.ledger.tick) {
245	        this.ledgerStep("reportDuelResult", reportDuelResult(this.ledger, { duelId: duel.id, tick, outcome: "cancelled" }));
246	      }
247	      if (duel.machine.outcome === undefined) duel.machine.end(null, "cancelled");
248	      duel.ended = true;
249	      duel.endedByRules = true;
250	      duel.removeAfterTick ??= tick + DUEL_RESULT_TICKS;
251	      this.state.markers.delete(duel.key);
252	    }
253	    outcomes.push({ code: this.state.code, results });
254	    console.log(`match ${this.state.code} ended at tick ${tick}: ${results.reason}${results.winner === null ? ", no winner" : `, won by ${results.winner}`}`);
255	  }
