257	  /**
258	   * §2 and §5's reveals, one world tick after the flow: the intel module reads the ledger's rubbings and the ships,
259	   * and the room delivers only its reveal messages, each to exactly its recipients (§16): the final island's sector to
260	   * everyone, its exact claim point only to a full-set holder. Rumors and the journal come with `intel-online`.
261	   */
262	  private stepReveals(tick: number): void {
263	    if (this.intelConfig === undefined || this.intel === undefined) return;
264	    const stepped = stepIntel(this.intelConfig, this.intel, this.intelView(tick));
265	    this.intel = stepped.state;
266	    for (const { to, body } of stepped.messages) {
267	      const reveal = revealOf(body);
268	      if (reveal === undefined) continue;
269	      if (reveal.kind === "final-sector") {
270	        this.state.finalSector = reveal.name;
271	        this.state.finalSectorIndex = reveal.sector;
272	      }
273	      const recipients = revealRecipients(to, [...this.clients].map((client) => client.sessionId));
274	      for (const id of recipients) {
275	        if (reveal.kind === "final-route") this.routes.set(id, { active: true, x: reveal.x, y: reveal.y });
276	        if (reveal.kind === "final-route-inactive") {
277	          const route = this.routes.get(id);
278	          if (route !== undefined) route.active = false;
279	        }
280	        this.clients.get(id)?.send(MatchMessageType.Reveal, reveal);
281	      }
282	    }
283	  }
