285	  /**
286	   * The world as the intel module reads it: every player in the match at their ship, and every rubbing where the
287	   * ledger has it. A player who left while a duel still reserves their rubbings stays in the view, at the position
288	   * they left from, until that duel settles.
289	   */
290	  private intelView(tick: number): IntelWorldView {
291	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
292	    const holding = new Set(this.ledger.rubbings.flatMap((rubbing) => (rubbing.location.kind === "duel" ? [rubbing.location.playerId] : [])));
293	    const players = this.ledger.players.flatMap((player) => {
294	      const ship = ships.get(player.id);
295	      if (player.status !== "left" && ship !== undefined) return [{ id: player.id, x: ship.x, y: ship.y }];
296	      if (holding.has(player.id)) return [{ id: player.id, x: player.exit?.x ?? 0, y: player.exit?.y ?? 0 }];
297	      return [];
298	    });
299	    const rubbings: IntelRubbing[] = this.ledger.rubbings.map((rubbing) => {
300	      const location = rubbing.location;
301	      switch (location.kind) {
302	        case "source": {
303	          const source = this.ledger.sources.find((each) => each.id === location.sourceId)!;
304	          return { id: rubbing.id, type: rubbing.type, place: { kind: "source", island: source.island, x: source.x, y: source.y } };
305	        }
306	        case "cache": {
307	          const cache = this.ledger.caches.find((each) => each.id === location.cacheId)!;
308	          return { id: rubbing.id, type: rubbing.type, place: { kind: "cache", x: cache.x, y: cache.y } };
309	        }
310	        case "player":
311	          return { id: rubbing.id, type: rubbing.type, place: { kind: "carried", playerId: location.playerId } };
312	        case "duel":
313	          return { id: rubbing.id, type: rubbing.type, place: { kind: "duel", playerId: location.playerId } };
314	      }
315	    });
316	    return { tick, players, rubbings };
317	  }
