327	  /** The private host's start request (§2): rate-capped and validated, then judged by the flow on the next tick. */
328	  private receiveStart(sessionId: string, message: unknown): void {
329	    const frame = this.simulation.frame;
330	    const rate = this.startRate.get(sessionId) ?? { windowStart: frame, count: 0 };
331	    if (frame - rate.windowStart >= STEPS_PER_SECOND) {
332	      rate.windowStart = frame;
333	      rate.count = 0;
334	    }
335	    rate.count++;
336	    this.startRate.set(sessionId, rate);
337	    if (rate.count > MAX_START_MATCH_PER_SECOND) return;
338	    if (validateStartMatchMessage(message) === undefined) return;
339	    // Only a seated player sends messages (onJoin adds them to the ledger and the flow's reports first).
340	    this.flowReports.push({ kind: "start", playerId: sessionId });
341	  }
