343	  /** Every player gone: a match that left its lobby ends abandoned (§12), stepped once more before the room closes. */
344	  override onDispose(): void {
345	    if (this.flow.end !== null || this.flowReports.length === 0) return;
346	    const tick = Math.max(this.simulation.worldTick + 1, this.flow.tick + 1);
347	    // The leavers' rubbings went into caches since the last tick: those losses count before the end.
348	    if (this.inPlay()) this.reportAccomplishments(tick);
349	    const reports = this.flowReports;
350	    this.flowReports = [];
351	    this.stepFlowWith(tick, reports);
352	  }
