438	  /** §4's theft choice from a client: the winner of a duel at sea, in its window, for an eligible type. */
439	  private receiveTheftChoice(sessionId: string, message: unknown): void {
440	    const frame = this.simulation.frame;
441	    const rate = this.choiceRate.get(sessionId) ?? { windowStart: frame, count: 0 };
442	    if (frame - rate.windowStart >= STEPS_PER_SECOND) {
443	      rate.windowStart = frame;
444	      rate.count = 0;
445	    }
446	    rate.count++;
447	    this.choiceRate.set(sessionId, rate);
448	    if (rate.count > MAX_CHOOSE_THEFT_PER_SECOND) return;
449	    const choice = validateChooseTheftMessage(message);
450	    if (choice === undefined) return;
451	    const duel = [...this.seaDuels.values()].find((each) => each.key === choice.duel && each.players.includes(sessionId));
452	    if (duel === undefined) return;
453	    // The ledger checks that this player won, the window is open and the type is eligible; otherwise nothing changes.
454	    const stepped = chooseTheft(this.ledger, { duelId: duel.id, playerId: sessionId, type: choice.type, tick: this.simulation.worldTick });
455	    this.ledger = stepped.state;
456	    this.noteSettlements();
457	  }
