479	  /** Each newly settled ledger duel, in its players' notices: what was stolen and the gold that moved. */
480	  private noteSettlements(): void {
481	    for (const duel of this.ledger.duels) {
482	      if (duel.phase !== "settled" || this.noticed.has(duel.id)) continue;
483	      this.noticed.add(duel.id);
