488	  private noteSettlement(duel: LedgerDuel): void {
489	    const settlement = duel.settlement!;
490	    const result = duel.result!;
491	    // §2's results count a settled win or draw for both fighters; a cancelled duel (both gone, or the match's end)
492	    // counts for neither. The rubbing and gold it moved are counted from the ledger with the tick's accomplishments.
493	    if (result.outcome !== "cancelled") this.flowReports.push({ kind: "duel-ended", playerIds: duel.players, winner: result.outcome === "win" ? result.winner : null });
494	    for (const id of duel.players) {
495	      const notice = this.noticesOf(id);
496	      notice.settledAt = settlement.tick;
497	      notice.stolen = settlement.stolenType ?? "";
498	      notice.settledChoice = settlement.choice;
499	      notice.choiceDeadline = duel.choiceDeadline ?? 0;
500	      if (result.outcome !== "win") {
501	        notice.settledRole = "draw";
502	        notice.goldChange = 0;
503	      } else {
504	        const winner = result.winner === id;
505	        notice.settledRole = winner ? "winner" : "loser";
506	        notice.goldChange = winner ? settlement.gold : -settlement.gold;
507	      }
508	    }
509	  }
