511	  /**
512	   * After every world tick in development and tests: the ledger's own invariant, and the room's: every player the
513	   * ledger counts in the match has a ship, and every ship belongs to such a player.
514	   */
515	  private checkInvariants(tick: number): void {
516	    if (!this.tuning.checkInvariants) return;
517	    const problems = checkLedger(this.ledger);
518	    const ships = new Set(this.simulation.ships.map((ship) => ship.id));
519	    for (const player of this.ledger.players) {
520	      if (player.status !== "left" && !ships.has(player.id)) problems.push(`player ${player.id} is in the ledger's match without a ship`);
521	    }
522	    for (const id of ships) {
523	      const player = findPlayer(this.ledger, id);
524	      if (player === undefined || player.status === "left") problems.push(`ship ${id} has no player in the ledger's match`);
525	    }
526	    if (problems.length === 0) return;
527	    for (const problem of problems) this.violations.push(`tick ${tick}: ${problem}`);
528	    console.error(`match ${this.state.code} invariant violated at tick ${tick}: ${problems.join("; ")}`);
529	  }
