531	  /** Copies the plain simulation state into the synced schema, then updates what each client may see. */
532	  private mirror(): void {
533	    this.state.frame = this.simulation.frame;
534	    this.state.worldTick = this.simulation.worldTick;
535	    this.state.players = this.simulation.ships.length;
536	    this.mirrorFlow();
537	    const present = new Set<string>();
538	    for (const ship of this.simulation.ships) {
539	      present.add(ship.id);
540	      let synced = this.state.ships.get(ship.id);
541	      if (synced === undefined) {
542	        synced = new ShipSchema();
543	        synced.id = ship.id;
544	        synced.slot = ship.slot;
545	        this.state.ships.set(ship.id, synced);
546	      }
547	      synced.x = ship.x;
548	      synced.y = ship.y;
549	      synced.heading = ship.heading;
550	      synced.speed = ship.speed;
551	      synced.dock = ship.dock;
552	      // §5: "warn nearby players": a ship channelling the claim shows it to whoever sees that ship.
553	      const channel = this.claim?.channel ?? null;
554	      synced.claiming = channel?.playerId === ship.id;
555	      synced.claimHeld = synced.claiming ? channel!.progress : 0;
556	    }
557	    for (const id of [...this.state.ships.keys()]) if (!present.has(id)) this.state.ships.delete(id);
558	    this.mirrorEncounters(present);
559	    this.mirrorObjectives(present);
560	    this.updateViews();
561	  }
