563	  /**
564	   * §2's flow into the synced state, for everyone: the phase, the host, the players in the lobby, the ready countdown's
565	   * end, control start, the timer (`remaining`) and deadline, the final island's sector once announced (never its
566	   * position), and the results once the match has ended.
567	   */
568	  private mirrorFlow(): void {
569	    const flow = this.flow;
570	    this.state.phase = flow.phase;
571	    this.state.hostSeat = flow.host === null ? 0 : this.seatOf(flow.host);
572	    this.state.readyEndsAt = flow.readyTick === null ? 0 : flow.readyTick + this.flowConfig.readyTicks;
573	    this.state.controlStartTick = flow.controlStartTick ?? 0;
