cat >> apps/web/src/style.css <<'EOF'

/* §3: the ruin panel, over the sea while a ruin is open. */
#ruin-panel:not([hidden]) {
  position: absolute;
  top: 3rem;
  left: 50%;
  transform: translateX(-50%);
  width: min(34rem, calc(100% - 1.5rem));
  max-height: calc(100% - 4rem);
  overflow-y: auto;
  padding: 0.75rem 1rem;
  border-radius: 0.5rem;
  background: rgb(6 32 47 / 94%);
  border: 2px solid #c9a86a;
}

#ruin-panel h2 {
  margin: 0 0 0.25rem;
  font-size: 1.1rem;
}

#ruin-panel p {
  margin: 0.35rem 0;
}

.ruin-tablets {
  list-style: none;
  margin: 0.5rem 0;
  padding: 0;
  display: grid;
  gap: 0.35rem;
}

.ruin-tablets li {
  display: grid;
  grid-template-columns: 7.5rem 1fr;
  align-items: center;
  gap: 0.75rem;
  padding: 0.3rem 0.5rem;
  border-radius: 0.35rem;
  background: #3b3325;
  border: 1px solid #6b5a3a;
}

.ruin-tablets li[data-chosen]:not([data-chosen=""]) {
  border-color: #ffd98a;
  background: #5a4a2a;
}

.ruin-tablets button {
  font-size: 1rem;
  text-align: left;
}

.ruin-tablets .inscription {
  font-size: 1.05rem;
  color: #f4e8cc;
}

.ruin-grid:not([hidden]) {
  display: grid;
  grid-template-columns: repeat(var(--size, 4), 3rem);
  gap: 0.25rem;
  justify-content: center;
  margin: 0.5rem 0;
}

.ruin-grid .cell {
  width: 3rem;
  height: 3rem;
  display: grid;
  place-items: center;
  font-weight: 700;
  font-size: 1.2rem;
  border-radius: 0.3rem;
  background: #2a5670;
}

.ruin-grid .cell[data-kind="blocked"] {
  background: #4a3f36;
  color: #a08b73;
}

.ruin-grid .cell[data-kind="start"] {
  background: #3f7d4f;
}

.ruin-grid .cell[data-kind="goal"] {
  background: #9c7a2c;
}

.ruin-grid .cell[data-path="true"] {
  outline: 3px solid #ffd98a;
  outline-offset: -3px;
}

.ruin-buttons {
  display: flex;
  gap: 0.5rem;
}

.ruin-verdict {
  display: block;
  color: #ffd98a;
}
EOF
