    ["npx", "vitest", "run", "--project", "unit", "apps/server", "packages/protocol"],
    ["npx", "vitest", "run", "--project", "integration", "tests/integration/ruins.test.ts", "tests/integration/ledgerSeed.test.ts"],
  ],
  "server-rub": [
    ["npx", "vitest", "run", "--project", "integration", "tests/integration/ruins.test.ts", "tests/integration/rubbings.test.ts"],
  ],
  web: [["npx", "vitest", "run", "--project", "unit", "apps/web"]],
  e2e: [["npx", "--no-install", "playwright", "test", "--config=tests/e2e/playwright.config.ts", "tests/e2e/ruins.spec.ts"]],
  baseline: [],
};

function run(argv, cwd, env) {
  return new Promise((resolve) => {
    const child = spawn(argv[0], argv.slice(1), { cwd, env: { ...process.env, ...env }, stdio: ["ignore", "pipe", "pipe"] });
    let out = "";
    child.stdout.on("data", (chunk) => (out += chunk));
    child.stderr.on("data", (chunk) => (out += chunk));
    const timer = setTimeout(() => child.kill("SIGKILL"), 600_000);
    child.on("close", (code) => {
      clearTimeout(timer);
      resolve({ code, out });
    });
  });
}

function vitestFailures(file, lane) {
  if (!fs.existsSync(file)) return ["(no report)"];
  const report = JSON.parse(fs.readFileSync(file, "utf8"));
  const failed = [];
  for (const result of report.testResults ?? []) {
    const rel = path.relative(lane, result.name);
    const tests = result.assertionResults ?? [];
    for (const test of tests) if (test.status === "failed") failed.push(`${rel} › ${[...(test.ancestorTitles ?? []), test.title].join(" ")}`);
    if (result.status === "failed" && !tests.some((test) => test.status === "failed")) failed.push(`${rel} (file failed: ${(result.message ?? "").split("\n")[0].slice(0, 120)})`);
  }
  return failed;
}

function playwrightFailures(file) {
  if (!fs.existsSync(file)) return ["(no report)"];
  const report = JSON.parse(fs.readFileSync(file, "utf8"));
  const failed = [];
  const walk = (suite, trail) => {
    for (const spec of suite.specs ?? []) {
      const ok = spec.tests.every((test) => test.results.length > 0 && test.results.every((result) => result.status === "passed"));
      if (!ok) failed.push(`${spec.file} › ${spec.title}`);
    }
    for (const child of suite.suites ?? []) walk(child, trail);
  };
  for (const suite of report.suites ?? []) walk(suite, []);
  if ((report.errors ?? []).length > 0) failed.push(`(errors: ${report.errors.map((error) => (error.message ?? "").split("\n")[0]).join("; ").slice(0, 200)})`);
  return failed;
}

async function runSuite(suite, lane, tag) {
  const failures = [];
  for (const [index, argv] of COMMANDS[suite].entries()) {
    const report = path.join(J, `report-${tag}-${index}.json`);
    fs.rmSync(report, { force: true });
    if (argv[1] === "vitest") {
      await run([...argv, "--reporter=json", `--outputFile=${report}`], lane, {});
      failures.push(...vitestFailures(report, lane));
    } else {
      await run([...argv, "--reporter=json"], lane, { PLAYWRIGHT_JSON_OUTPUT_FILE: report });
      failures.push(...playwrightFailures(report));
    }
  }
  return failures;
}

async function worker(laneIndex) {
  const lane = path.join(J, `lane${laneIndex}`);
  for (;;) {
    const deletion = queue.shift();
    if (deletion === undefined) return;
    const target = path.join(lane, deletion.file);
    const original = fs.readFileSync(path.join(W, deletion.file), "utf8");
    const count = original.split(deletion.find).length - 1;
    if (count !== 1) {
      fs.appendFileSync(resultsFile, JSON.stringify({ id: deletion.id, error: `find occurs ${count} times` }) + "\n");
      continue;
    }
    fs.writeFileSync(target, original.replace(deletion.find, deletion.replace));
    const started = Date.now();
    let failures;
    try {
      failures = await runSuite(deletion.suite, lane, `${laneIndex}`);
    } finally {
      fs.writeFileSync(target, original);
    }
    const record = { id: deletion.id, suite: deletion.suite, failures, seconds: Math.round((Date.now() - started) / 1000) };
    fs.appendFileSync(resultsFile, JSON.stringify(record) + "\n");
    console.log(`${deletion.id}: ${failures.length} failing (${record.seconds}s)`);
  }
}

await Promise.all(lanes.map((lane) => worker(lane)));

